import{_ as t,o as a,c as d,aj as s}from"./framework.js";const m=JSON.parse('{"title":"Database | Database | Admin CMS","description":"The Database group manages multiple data stores within a site: IndexedDB dynamic tables, table relations, key-value storage, and browsing and data maintenance for external SQLite / MySQL…","frontmatter":{"title":"Database | Database | Admin CMS","description":"The Database group manages multiple data stores within a site: IndexedDB dynamic tables, table relations, key-value storage, and browsing and data maintenance for external SQLite / MySQL…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/database/index.html"}]]},"headers":[],"relativePath":"cms/database/index.md","filePath":"en/cms/database/index.md","lastUpdated":1781010536000}'),o={name:"cms/database/index.md"};function r(n,e,i,l,b,c){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h1><blockquote><p>Menu: <strong>Database</strong> group in the left sidebar (must be enabled in <strong>Edit Menu</strong>)<br> Route prefix: <code>/_Admin/database/...?SiteId={siteGuid}</code></p></blockquote><p>The <strong>Database</strong> group manages multiple data stores within a site: <strong>IndexedDB dynamic tables</strong>, table relations, <strong>key-value storage</strong>, and browsing and data maintenance for external <strong>SQLite / MySQL / SQL Server</strong> tables. <strong>SQL Logs</strong> shows SQL records produced by scripts and the admin backend. Scripts access these stores uniformly through <a href="/kb-docs/api/database/">k.DB</a> (for SQLite see <a href="/kb-docs/api/sqlite/">k.DB.sqlite</a>).</p><div class="tip custom-block"><p class="custom-block-title">Difference from Content</p><table tabindex="0"><thead><tr><th></th><th><strong>Database</strong></th><th><strong>Content → Content</strong></th></tr></thead><tbody><tr><td>Model</td><td>Custom table schemas, KV, external DB tables</td><td>Content types + content folders</td></tr><tr><td>Typical use</td><td>Business tables, cache keys, integrating existing SQL databases</td><td>CMS entries bindable to pages</td></tr><tr><td>API</td><td><code>k.DB</code></td><td><code>k.content</code></td></tr></tbody></table><p>The two can be used together; do not treat them as one modeling system.</p></div><div class="info custom-block"><p class="custom-block-title">Advanced menu</p><p>The Database group and its sub-items are marked <strong>advanced</strong> in Edit Menu. If they are not checked, this group does not appear in the left sidebar.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, check <strong>Database</strong> and the sub-items you need.</li><li>Expand <strong>Database</strong> in the left sidebar.</li></ol><h2 id="submenus-same-order-as-the-admin" tabindex="-1">Submenus (same order as the admin) <a class="header-anchor" href="#submenus-same-order-as-the-admin" aria-label="Permalink to &quot;Submenus (same order as the admin)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>Route</th><th>Permission (feature)</th><th>Doc</th></tr></thead><tbody><tr><td>IndexedDB Tables</td><td><code>/database/table</code></td><td><code>database</code></td><td><a href="./table.html">IndexedDB tables</a> (this section)</td></tr><tr><td>IndexedDB Table Relations</td><td><code>/database/table-relation</code></td><td><code>tableRelation</code></td><td><a href="./table-relation.html">Table relations</a></td></tr><tr><td>Key-Value Storage</td><td><code>/database/key-value</code></td><td><code>keyValue</code></td><td><a href="./key-value.html">Key-value storage</a></td></tr><tr><td>SQLite Tables</td><td><code>/database/sqlite-table</code></td><td><code>database</code></td><td><a href="./sqlite-table.html">SQLite tables</a></td></tr><tr><td>MySQL Tables</td><td><code>/database/mysql-table</code></td><td><code>database</code></td><td><a href="./mysql-table.html">MySQL tables</a></td></tr><tr><td>SQL Server Tables</td><td><code>/database/sqlserver-table</code></td><td><code>database</code></td><td><a href="./sqlserver-table.html">SQL Server tables</a></td></tr><tr><td>SQL Logs</td><td><code>/database/sql-logs</code></td><td><code>database·log</code></td><td><a href="./sql-logs.html">SQL logs</a></td></tr></tbody></table><h3 id="development-reference-kscript-api" tabindex="-1">Development reference (KScript API) <a class="header-anchor" href="#development-reference-kscript-api" aria-label="Permalink to &quot;Development reference (KScript API)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Menu</th><th>API doc</th></tr></thead><tbody><tr><td>IndexedDB tables</td><td><a href="/kb-docs/api/indexed-db/">k.DB.indexedDb</a></td></tr><tr><td>SQLite / MySQL / SQL Server tables</td><td><a href="/kb-docs/api/database/">k.DB</a> · <a href="/kb-docs/api/sqlite/">k.DB.sqlite</a></td></tr><tr><td>Key-value storage</td><td><a href="/kb-docs/api/database/">k.DB</a> (KV APIs; see child doc)</td></tr><tr><td>SQL logs</td><td>Read-only observation; no dedicated <code>k.*</code> CRUD</td></tr></tbody></table><h2 id="edit-routes-without-sidebar-menu-items" tabindex="-1">Edit routes without sidebar menu items <a class="header-anchor" href="#edit-routes-without-sidebar-menu-items" aria-label="Permalink to &quot;Edit routes without sidebar menu items&quot;">​</a></h2><p>The following pages are opened from table lists. Breadcrumbs still belong to the corresponding table-type menu (<code>dbType</code> query parameter highlights <strong>IndexedDB / SQLite / MySQL / SQL Server</strong>):</p><table tabindex="0"><thead><tr><th>Route</th><th>Description</th></tr></thead><tbody><tr><td><code>/database/table/columns</code></td><td>Edit table columns (column definitions)</td></tr><tr><td><code>/database/table/data</code></td><td>Browse and filter table data</td></tr><tr><td><code>/database/table/edit-data</code></td><td>Create or edit a single row</td></tr></tbody></table><p>Deep-link examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/database/table/columns?SiteId={siteGuid}&amp;id={tableId}&amp;dbType=IndexedDb</span></span>
<span class="line"><span>/_Admin/database/table/data?SiteId={siteGuid}&amp;id={tableId}&amp;dbType=Sqlite</span></span></code></pre></div><p><code>dbType</code> values match the admin (e.g. <code>IndexedDb</code>, <code>Sqlite</code>, <code>Mysql</code>, <code>SqlServer</code>); confirm in the address bar.</p><h2 id="suggested-reading-order" tabindex="-1">Suggested reading order <a class="header-anchor" href="#suggested-reading-order" aria-label="Permalink to &quot;Suggested reading order&quot;">​</a></h2><p>If you are modeling site data from scratch, a common order is:</p><ol><li><strong><a href="./table.html">IndexedDB tables</a></strong> — default dynamic tables within the site</li><li><strong><a href="./table-relation.html">Table relations</a></strong> — multi-table associations (requires existing IndexedDB tables)</li><li><strong><a href="./key-value.html">Key-value storage</a></strong> — simple KV</li><li><strong>SQLite / MySQL / SQL Server</strong> — read as needed depending on external database integration</li><li><strong><a href="./sql-logs.html">SQL logs</a></strong> — troubleshooting and auditing</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../navigation.html">Site admin menu overview</a></td><td>Full menu tree</td></tr><tr><td><a href="./../development/">Development</a></td><td>Calling <code>k.DB</code> from Code</td></tr><tr><td><a href="/kb-docs/api/database/">k.DB</a></td><td>Script API</td></tr><tr><td><a href="/kb-docs/api/sqlite/">k.DB.sqlite</a></td><td>SQLite queries and table operations</td></tr></tbody></table>`,22)])])}const u=t(o,[["render",r]]);export{m as __pageData,u as default};
